use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() < 3 { continue }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut v: int = 0
        for c in parts[0].chars() {
            let d: int = if c >= 'A' && c <= 'Z' {
                (c as int) - ('A' as int) + 10
            } else {
                (c as int) - ('0' as int)
            }
            v = v * from + d
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        let dc: Vec<char> = digits.chars().collect()
        while v > 0 {
            out.push(dc[(v % to) as usize])
            v = v / to
        }
        let mut s = ""
        let mut i = out.len()
        while i > 0 {
            i -= 1
            s = s + &out[i].to_string()
        }
        println("${s}")
    }
}

